<template>
  <main class="ai-chat-page">
    <header class="page-heading"><div class="heading-main"><span class="heading-icon"><el-icon><ChatDotRound/></el-icon></span><div><span class="eyebrow">AI WORKSPACE</span><h1>商品 AI 对话</h1><p>围绕商品持续讨论，让 AI 按需查询资料、分析经营与优化方向。</p></div></div><el-button :icon="Refresh" :loading="loading" @click="refresh">刷新</el-button></header>
    <section class="catalog-card">
      <div class="filter-panel">
        <div class="filter-field search-field"><label>查找商品</label><el-input v-model="query" :prefix-icon="Search" placeholder="ASIN / SKU / 中文名 / Listing标题" clearable @keyup.enter="applyFilters" @clear="applyFilters"/></div>
        <div class="filter-field"><label>店铺</label><el-select v-model="shopId" filterable clearable placeholder="全部店铺" @change="applyFilters"><el-option v-for="shop in shops" :key="shop.id" :value="String(shop.id)" :label="shop.name"/></el-select></div>
        <div class="filter-field"><label>当前负责人 <el-tooltip content="按当前已生效的SKU归属筛选，不将托管启用人或未来预约负责人当成当前负责人。" placement="top"><el-icon class="field-help"><QuestionFilled/></el-icon></el-tooltip></label><el-select v-model="ownerId" filterable clearable placeholder="全部负责人" @change="applyFilters"><el-option value="none" label="未分配负责人"/><el-option v-for="owner in owners" :key="owner.id" :value="String(owner.id)" :label="owner.name || `人员 #${owner.id}`"><span>{{ owner.name || `人员 #${owner.id}` }}</span><el-tag v-if="owner.account_type==='ai'" size="small" type="info" class="option-ai">AI运营</el-tag></el-option></el-select></div>
        <div class="filter-field"><label>托管状态</label><el-select v-model="managed" @change="applyFilters"><el-option value="all" label="全部托管状态"/><el-option value="yes" label="已托管（含暂停）"/><el-option value="active" label="已托管 · 已启用"/><el-option value="paused" label="已托管 · 已暂停"/><el-option value="no" label="未托管"/></el-select></div>
        <div class="filter-actions"><el-button type="primary" :icon="Search" @click="applyFilters">查询</el-button><el-button @click="reset">重置</el-button></div>
      </div>
      <div class="catalog-heading"><div><strong>商品列表</strong><span class="result-count">{{ loading?'正在查询…':`当前筛选 ${total.toLocaleString()} 个商品` }}</span></div><span class="reading-note"><el-icon><InfoFilled/></el-icon> 打开对话不计费，发送消息后才调用 AI</span></div>
      <el-alert v-if="error" class="catalog-error" :title="error" type="error" :closable="false" show-icon/>
      <el-table :data="rows" v-loading="loading" row-key="id" class="product-table">
        <el-table-column label="商品信息" min-width="430"><template #default="{row}"><div class="product-cell">
          <el-image v-if="row.main_image_url" class="product-image" :src="row.main_image_url" fit="contain" :preview-src-list="[row.main_image_url]" preview-teleported hide-on-click-modal><template #error><div class="image-placeholder"><el-icon><Picture/></el-icon><span>图片不可用</span></div></template></el-image><div v-else class="product-image image-placeholder"><el-icon><Picture/></el-icon><span>暂无图片</span></div>
          <div class="product-copy"><strong class="product-name" :title="row.product_name || row.item_name">{{ row.product_name || row.item_name || '未维护商品名称' }}</strong><div v-if="row.product_name && row.item_name && row.product_name!==row.item_name" class="listing-title" :title="row.item_name">{{ row.item_name }}</div><div class="product-identities"><span class="identity-label">ASIN</span><a :href="`https://www.amazon.com/dp/${encodeURIComponent(row.asin)}`" target="_blank" rel="noopener noreferrer">{{ row.asin }} <el-icon><TopRight/></el-icon></a><span class="identity-label sku-label">SKU</span><span class="sku-text" :title="row.sku">{{ row.sku }}</span></div></div>
        </div></template></el-table-column>
        <el-table-column label="店铺 / 站点" min-width="145"><template #default="{row}"><div class="shop-name">{{ row.shop_name }}</div><span class="market-badge">美国站 · US</span></template></el-table-column>
        <el-table-column label="当前负责人" min-width="165"><template #default="{row}"><el-tag v-if="row.owner_conflict" type="danger" effect="light">归属记录异常</el-tag><div v-else-if="row.owner_id" class="owner-cell"><span class="owner-avatar" :class="{robot:row.owner_type==='ai'}">{{ row.owner_type==='ai'?'AI':(row.owner_name || '#').slice(0,1) }}</span><div><strong>{{ row.owner_name || `人员 #${row.owner_id}` }}</strong><small>{{ row.owner_type==='ai'?'AI运营账号':'当前已生效归属' }}</small></div></div><span v-else class="unassigned">未分配负责人</span></template></el-table-column>
        <el-table-column label="托管状态" width="155"><template #default="{row}"><el-tag round effect="light" :type="!row.is_managed?'info':row.enabled?'success':'warning'"><span class="status-dot"/>{{ row.is_managed?'已托管':'未托管' }}</el-tag><div class="status-note">{{ !row.is_managed?'仅人工发起分析':row.enabled?'每日任务已启用':'每日任务已暂停' }}</div></template></el-table-column>
        <el-table-column label="操作" width="150" align="right" fixed="right"><template #default="{row}"><el-button type="primary" plain :icon="ChatDotRound" @click="dialog.open({shop_id:row.shop_id,asin:row.asin})">进入对话</el-button></template></el-table-column>
        <template #empty><div class="catalog-empty"><el-icon><Search/></el-icon><strong>{{ error?'商品列表读取失败':'没有找到匹配的商品' }}</strong><span>{{ error?'请检查上方提示后重试。':'可以调整搜索、负责人或托管状态；这里只展示有权限访问的商品。' }}</span><el-button v-if="!error" link type="primary" @click="reset">清空筛选</el-button></div></template>
      </el-table>
      <footer class="catalog-footer"><span>未托管商品也可讨论或生成方案，不会自动开启每日托管。</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20,50,100]" :total="total" layout="total, sizes, prev, pager, next" :disabled="loading" @current-change="load" @size-change="resizePage"/></footer>
    </section>
    <AiConversationDialog ref="dialog"/>
  </main>
</template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {ChatDotRound,Refresh,Search,Picture,TopRight,InfoFilled,QuestionFilled} from '@element-plus/icons-vue'
import {getAiProducts} from '@/services/ai/workspace'
import AiConversationDialog from '@/components/ai/conversation/AiConversationDialog.vue'
const query=ref(''),managed=ref('all'),shopId=ref(''),ownerId=ref(''),rows=ref([]),total=ref(0),loading=ref(false),error=ref(''),dialog=ref(null)
const shops=ref([]),owners=ref([]),page=ref(1),pageSize=ref(20)
let active=true,version=0,optionsReady=false
/** 筛选、总数和分页统一由服务端计算；迟到结果不覆盖当前查询。 */
async function load(){const seq=++version;loading.value=true;error.value='';try{const {data}=await getAiProducts({q:query.value,managed:managed.value,shop_id:shopId.value || undefined,owner_id:ownerId.value || undefined,page:page.value,page_size:pageSize.value,include_filters:optionsReady?undefined:1});if(active && seq===version){rows.value=data.data.list;total.value=data.data.total;if(data.data.filters){shops.value=data.data.filters.shops;owners.value=data.data.filters.owners;optionsReady=true}}}catch(e){if(active && seq===version){error.value=e.response?.data?.message || '商品列表读取失败';rows.value=[];total.value=0;if(e.response?.status===403){shops.value=[];owners.value=[];optionsReady=false}}}finally{if(active && seq===version)loading.value=false}}
function applyFilters(){page.value=1;load()}
function resizePage(){page.value=1;load()}
function reset(){query.value='';shopId.value='';ownerId.value='';managed.value='all';applyFilters()}
function refresh(){optionsReady=false;load()}
onMounted(load);onBeforeUnmount(()=>{active=false;version++})
</script>
