ddle}.status-note{font-size:10px;color:#9aa8bb;margin-top:7px}.catalog-footer{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:20px 24px;border-top:1px solid #edf1f6;flex-wrap:wrap}.catalog-footer>span{font-size:11px;color:#98a6ba}.catalog-footer .el-pagination{padding:0}.catalog-empty{display:flex;align-items:center;flex-direction:column;gap:10px;padding:42px 20px;color:#9aa9bc;line-height:1.7}.catalog-empty>.el-icon{font-size:32px;color:#c6d2e3}.catalog-empty strong{font-size:14px;font-weight:500;color:#8193ab}.catalog-empty span{font-size:12px}.option-ai{margin-left:10px}@media(min-width:1800px){.ai-chat-page{padding:32px 44px}.filter-panel{grid-template-columns:minmax(320px,2fr) repeat(3,minmax(180px,1fr)) auto}}@media(max-width:1200px){.filter-panel{grid-template-columns:repeat(3,minmax(140px,1fr))}.search-field{grid-column:span 2}.filter-actions{justify-content:flex-end}.reading-note{display:none}}@media(max-width:700px){.ai-chat-page{padding:18px 12px}.page-heading{gap:12px}.heading-icon{width:42px;height:42px;border-radius:12px;font-size:23px}.heading-main{gap:10px}.page-heading h1{font-size:20px}.page-heading p{font-size:11px}.eyebrow{display:none}.filter-panel{padding:16px;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.search-field{grid-column:span 2}.filter-actions{justify-content:flex-start}.catalog-heading{padding:18px 16px}.catalog-footer{padding:16px}.catalog-footer :deep(.el-pagination__sizes){display:none}}
